/**
 * PriceDisplay — renders a price with the currency and amount in separate
 * spans so consumers can style each independently via CSS.
 *
 * Why separate spans:
 *   - Multi-currency stores often want the currency code/symbol smaller or
 *     dimmer than the amount (e.g., "USD 19.99" with "USD" at 0.8em).
 *   - Some designs strike through the amount but leave the currency code
 *     legible.
 *   - Right-to-left locales / typography tweaks (tabular-nums on the
 *     numeric portion) are easier when the amount is its own span.
 *
 * The component is a thin wrapper around `formatPriceParts` from
 * `omniguide-core`. Style behavior (which characters end up where) is
 * documented in detail there; this file is just the React shell.
 *
 * Class names:
 *   - .omniguide-price                  (root span)
 *   - .omniguide-price__currency        (leading or trailing currency token)
 *   - .omniguide-price__amount          (numeric portion)
 *
 * Returns null when the value is non-finite (NaN / Infinity) — caller
 * decides whether to show a placeholder.
 */

import React, { memo } from 'react';
import {
  createScopedLogger,
  formatPriceParts,
  resolvePriceFormat,
  type PriceFormatConfig,
} from '@swiftotter/omniguide-core';

const log = createScopedLogger('PriceDisplay');

export interface PriceDisplayProps {
  value: number | null | undefined;
  /**
   * ISO 4217 code. When omitted or null, the amount is rendered with no
   * currency token (locale-aware decimal, e.g. `1,299.99` / `1 299,99`).
   *
   * This is the "loud-fail" path — if you see prices without a currency
   * token in the UI, the backend omitted `currency` and no consumer
   * fallback was configured. Either (a) ask the backend team to emit
   * `currency` per price object, or (b) for single-currency stores, set
   * `defaultCurrency` (carousel) / `currency` (PLP) at the integration
   * boundary.
   */
  currency?: string | null;
  /** BCP-47 locale tag. Defaults to en-US. Drives number formatting + symbol disambiguation. */
  locale?: string;
  /** Either a single style or a per-currency config. See `PriceFormatConfig`. */
  priceFormat?: PriceFormatConfig;
  /** Extra className appended to the root span (e.g., "omniguide-carousel-card__price-current"). */
  className?: string;
}

// One-time per page-load warning when we render without a currency
// token. Quiet on subsequent prices so DevTools doesn't get spammed.
let __omniguideCurrencyFallbackWarned = false;
function warnCurrencyFallbackOnce(): void {
  if (__omniguideCurrencyFallbackWarned) return;
  __omniguideCurrencyFallbackWarned = true;
  log.warn(
    'Rendering price without a currency token — backend price omitted `currency` and no consumer fallback was set. ' +
    'Fix preferred: backend team should add `currency` to every price object. ' +
    'Stopgap for single-currency stores: pass `defaultCurrency` to CarouselContainer / `currency` to renderProductList.',
  );
}

function PriceDisplayImpl({
  value,
  currency,
  locale = 'en-US',
  priceFormat,
  className,
}: PriceDisplayProps): JSX.Element | null {
  if (value === null || value === undefined) return null;
  if (!Number.isFinite(value)) return null;

  const rootClass = className ? `omniguide-price ${className}` : 'omniguide-price';

  // No-currency path — render the amount only via Intl decimal formatting.
  // Skip the currency-style/Intl-currency machinery entirely.
  if (currency == null || currency === '') {
    warnCurrencyFallbackOnce();
    let amount: string;
    try {
      amount = new Intl.NumberFormat(locale, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }).format(value);
    } catch {
      amount = value.toFixed(2);
    }
    return (
      <span className={rootClass}>
        <span className="omniguide-price__amount">{amount}</span>
      </span>
    );
  }

  const style = resolvePriceFormat(currency, priceFormat);
  const parts = formatPriceParts(value, currency, locale, style);
  if (!parts) return null;

  return (
    <span className={rootClass}>
      {parts.leadingCurrency !== null ? (
        <span className="omniguide-price__currency">{parts.leadingCurrency}</span>
      ) : null}
      <span className="omniguide-price__amount">{parts.amount}</span>
      {parts.trailingCurrency !== null ? (
        <span className="omniguide-price__currency">{parts.trailingCurrency}</span>
      ) : null}
    </span>
  );
}

export const PriceDisplay = memo(PriceDisplayImpl);
PriceDisplay.displayName = 'PriceDisplay';
